import { render } from '@solidjs/web';
import { createContext, useContext, createStore } from 'solid-js';

const Theme = createContext();
function ThemeProvider(props) {
  const [state, setState] = createStore({
    color: '#335d92',
    title: 'Context Example',
  });
  const value = [
    state,
    (color) =>
      setState((draft) => {
        draft.color = color;
      }),
  ];
  return <Theme value={value}>{props.children}</Theme>;
}
function ColorPicker() {
  const [theme, changeColor] = useContext(Theme);
  return (
    <>
      <h1 style={{ color: theme.color }}>{theme.title}</h1>
      <label>
        Change color{' '}
        <input
          type="color"
          value={theme.color}
          onInput={(event) => changeColor(event.currentTarget.value)}
        />
      </label>
    </>
  );
}
function App() {
  return (
    <ThemeProvider>
      <ColorPicker />
    </ThemeProvider>
  );
}

render(() => <App />, document.getElementById('app'));
